from lib import *
import math, random
def cover_svg():
    random.seed(7); W,H=210,297; out=[f'<svg class="art" viewBox="0 0 {W} {H}" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0a1f2b"/><stop offset=".45" stop-color="#14495a"/><stop offset=".72" stop-color="#6fb3b0"/><stop offset="1" stop-color="#e8d9a8"/></linearGradient></defs><rect width="{W}" height="{H}" fill="url(#sky)"/>']
    for i in range(160):
        out.append(f'<circle cx="{random.uniform(0,W):.1f}" cy="{random.uniform(0,150):.1f}" r="{random.uniform(.12,.4):.2f}" fill="#fff" opacity="{random.uniform(.3,.9):.2f}"/>')
    layers=[(196,56,"#9fc4d0",.55,3.0,"#ffffff"),(212,50,"#6f9fb0",.7,2.3,"#e9f4f8"),(234,44,"#3d7c78",.85,1.7,None),(254,38,"#235c4d",1,1.3,None),(272,30,"#143d33",1,1.0,None),(290,20,"#0b2a22",1,.8,None)]
    for base,amp,col,op,fr,cap in layers:
        ph=random.uniform(0,6); pts=[]
        for x in range(0,W+3,3):
            y=base-amp*(0.55*abs(math.sin(x/(34/fr)+ph))+0.3*abs(math.sin(x/(13/fr)+ph*2))+0.15*random.random())
            pts.append((x,y))
        d="M0,%d "%H+" ".join(f"L{x},{y:.1f}" for x,y in pts)+f" L{W},{H} Z"
        out.append(f'<path d="{d}" fill="{col}" opacity="{op}"/>')
        if cap:
            cp=[(x,y) for x,y in pts if y<base-amp*0.62]
            for x,y in cp: out.append(f'<path d="M{x-1.6},{y+2.4:.1f} L{x},{y:.1f} L{x+1.6},{y+2.4:.1f}Z" fill="{cap}" opacity=".85"/>')
    # conifers
    for k in range(70):
        x=random.uniform(0,W); y=random.uniform(272,296); s=random.uniform(3,8)
        out.append(f'<path d="M{x:.1f},{y:.1f} l{-s/3:.1f},{s:.1f} h{2*s/3:.1f}Z M{x:.1f},{y+s*.5:.1f} l{-s/2.4:.1f},{s:.1f} h{s/1.2:.1f}Z" fill="#06180f"/>')
    out.append('</svg>'); return "".join(out)
def pages():
    P=[]
    cover=f'''<section class="page cover" data-n="@@PN@@">{cover_svg()}<div class="ttl"><div class="kick">אנציקלופדיה מדעית-גאוגרפית מאוירת</div><h1>עולמות<br>פראיים</h1><h2>ההרים, הפארקים הלאומיים והמערכות האקולוגיות של כדור הארץ</h2></div>
<div class="bottom"><span>פארקים לאומיים · מערכות הרים · צפון אמריקה · אקולוגיה · קרחונים</span><span class="lat" style="font-family:Frank,serif">WILD WORLDS</span></div></section>'''
    P.append(dict(raw=cover))
    intro=f'''
<p><b>עולמות פראיים</b> מנסה לענות על שאלה אחת: כיצד כדור הארץ בונה הרים, מעצב נופים, מקיים מערכות אקולוגיות ויוצר את עולמות הטבע המרהיבים שלו? הספר מתחיל מהפארקים הלאומיים של המערב האמריקאי, יחידות מחקר ושימור מושלמות, ומרחיב את המבט אל מערכות ההרים הגדולות בעולם, אל הרי צפון אמריקה, אל מגוון המערכות האקולוגיות ולבסוף אל הקרח, המנוע שמעצב את כולן.</p>
<h2>מבנה הספר</h2>
{table([["א׳","הפארקים הלאומיים של ארצות הברית","14"],["ב׳","מערכות ההרים בעולם","8"],["ג׳","הרי צפון אמריקה","8"],["ד׳","המערכות האקולוגיות של כדור הארץ","8"],["ה׳","קרחונים ותהליכים קרחוניים","2"]],["חלק","נושא","עמודים"])}
<p>היחס בין החלקים (35, 20, 20, 20 ו-5 אחוזים) נשמר: אף נושא אינו משתלט על האחרים. ידע גלציולוגי, גאולוגי ואקולוגי משולב גם בחלקים אחרים, כשהדבר רלוונטי.</p>
<h2>שלושה סימנים לאורך הדרך</h2>
{box("journey","מסעות גאוגרפיים","<p>קטעי מסע שמובילים את הקורא לאורך חתך אמיתי של גובה, אקלים וצמחייה.</p>")}
{box("compare","השוואות","<p>הצבה זו לצד זו של אזורים: האלפים והרוקי, יער גשם ממוזג וטרופי, קרחונים בשתי יבשות.</p>")}
{box("nature","מדורי טבע","<p>תיבות קצרות המסבירות תופעה: אגמים טורקיזיים, קו העצים, פרחים אלפיניים ועוד.</p>")}
<h2>איך נקראים הנתונים</h2>
<p>גבהים במטרים מעל פני הים; שטחים בקילומטרים רבועים; טמפרטורות במעלות צלזיוס; משקעים במילימטרים בשנה; גילאים גאולוגיים במיליוני שנים (״מ״ש״, Ma) או במיליארדי שנים. סימן ״~״ או ״כ-״ מציין הערכה או נתון המשתנה לפי מקור ושיטת מדידה; כך, למשל, גובה מון בלאן משתנה במדידות עוקבות בגלל כיפת השלג שמעליו. הנתונים נאספו ממוסדות מדעיים, ורשימת המקורות בסוף הספר.</p>
{box("data","הערה על האיורים ועל אימות הנתונים","<p><b>המפות</b> הן מפות רליף שנוצרו לספר זה ממערך הנתונים ETOPO1 של NOAA ומתמונת Blue Marble של NASA, ברזולוציה של כ-7 ק״מ לפיקסל. <b>האיורים המדעיים</b> (חתכים, תרשימים) הם איורים סכמטיים שנוצרו במיוחד לספר, ואינם צילומים ואינם בקנה מידה. בספר <b>אין צילומי טבע</b>. הנתונים הוצגו מזיכרון מקצועי על סמך מקורות מוסדיים ואקדמיים שנזכרו, ולא אומתו מחדש בגישה ישירה למקורות בזמן ההפקה; לפני ציטוט מחייב יש להשוות לגרסה העדכנית של המקור.</p>")}
'''
    P.append(page(0,"פתיחה","מבוא: מה בונה עולם פראי","Introduction",intro,hero=sf("world","<b>מערכות הרים נבחרות בעולם</b> על רקע רליף (NOAA ETOPO1). הנקודות הכתומות הן המערכות הנסקרות בחלק ב׳, הלבנות מערכות נוספות. רזולוציית הרליף כ-7 ק״מ.",""),notoc=True,band="פתיחה"))
    toc='''@@TOC@@'''
    P.append(page(0,"תוכן","תוכן עניינים","Contents",toc,notoc=True,band="תוכן עניינים"))
    return P
